class Solution:
    def maxScore(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        best, bk = None, None
        for k in range(2, max(nums) + 2):
            cur, mn, mx = 0, 0, float('-inf')
            for x in nums:
                cur += x if x % k == 0 else -x
                mx = max(mx, cur - mn)
                mn = min(mn, cur)
            if best is None or mx > best:
                best, bk = mx, k
        return (best * bk) % MOD

