    int maxScore(vector<int>& nums) {
        const long long MOD = 1e9 + 7;
        int V = *max_element(nums.begin(), nums.end());
        long long best = LLONG_MIN, bk = 0;
        for (long long k = 2; k <= V + 1; ++k) {
            long long cur = 0, mn = 0, mx = LLONG_MIN;
            for (int x : nums) {
