                mx = max(mx, cur - mn);
                mn = min(mn, cur);
            }
            if (mx > best) { best = mx; bk = k; }
        }
        long long ans = (best % MOD) * (bk % MOD) % MOD;
        return (int)((ans % MOD + MOD) % MOD);
    }
};

