class Solution {
public:
    int maxScore(vector<int>& nums) {
        const long long MOD = 1e9 + 7;
        set<long long> cands;
        for (int x : nums) {
            for (long long d = 2; d * d <= x; ++d)
                if (x % d == 0) { cands.insert(d); cands.insert(x / d); }
            if (x >= 2) cands.insert(x);
        }
        long long k = 2;
        while (true) {
            bool div = false;
            for (int x : nums) if (x % k == 0) { div = true; break; }
            if (!div) break;
            ++k;
        }
        cands.insert(k);
        long long best = LLONG_MIN, bk = 0;
        for (long long kk : cands) {
            long long cur = 0, mn = 0, mx = LLONG_MIN;
            for (int x : nums) {
                cur += (x % kk == 0) ? x : -x;
                mx = max(mx, cur - mn);
                mn = min(mn, cur);
            }
            if (mx > best) { best = mx; bk = kk; }
        }
        long long ans = (best % MOD) * (bk % MOD) % MOD;
        return (int)((ans % MOD + MOD) % MOD);
    }
};

